	beforeEach(() => {
		root = mkdtempSync(join(tmpdir(), "core-plugin-uninstall-"));
		home = join(root, "home");
		originalHome = process.env.HOME;
		originalClineDir = process.env.CLINE_DIR;
		originalClineDataDir = process.env.CLINE_DATA_DIR;
		originalGlobalSettingsPath = process.env.CLINE_GLOBAL_SETTINGS_PATH;
		originalMcpSettingsPath = process.env.CLINE_MCP_SETTINGS_PATH;
		process.env.HOME = home;
		process.env.CLINE_DIR = join(home, ".cline");
		process.env.CLINE_DATA_DIR = join(home, ".cline", "data");
		process.env.CLINE_GLOBAL_SETTINGS_PATH = join(
			home,
			".cline",
			"data",
			"settings",
			"global-settings.json",
		);
		setHomeDir(home);
		setClineDir(process.env.CLINE_DIR);
	});

	afterEach(() => {
		if (originalHome === undefined) {
			delete process.env.HOME;
		} else {
			process.env.HOME = originalHome;
		}
		if (originalClineDir === undefined) {
			delete process.env.CLINE_DIR;
		} else {
			process.env.CLINE_DIR = originalClineDir;
		}
		if (originalClineDataDir === undefined) {
			delete process.env.CLINE_DATA_DIR;
		} else {
			process.env.CLINE_DATA_DIR = originalClineDataDir;
		}
		if (originalGlobalSettingsPath === undefined) {
			delete process.env.CLINE_GLOBAL_SETTINGS_PATH;
		} else {
			process.env.CLINE_GLOBAL_SETTINGS_PATH = originalGlobalSettingsPath;
		}
		if (originalMcpSettingsPath === undefined) {
			delete process.env.CLINE_MCP_SETTINGS_PATH;
		} else {
			process.env.CLINE_MCP_SETTINGS_PATH = originalMcpSettingsPath;
		}
		rmSync(root, { recursive: true, force: true });
	});

	it("uninstalls an installed package plugin by package name", async () => {
		const installPath = join(
			home,
			".cline",
			"plugins",
			"_installed",
			"local",
			"bundled-skills-demo-123456789abc",
		);
		const entryPath = join(installPath, "package", "index.ts");
		await mkdir(join(installPath, "package"), { recursive: true });
		await writeFile(
			join(installPath, "package.json"),
			JSON.stringify(
				{
					name: "cline-installed-plugin-test",
					cline: {
						plugins: [{ paths: ["./package/index.ts"] }],
					},
				},
				null,
				2,
			),
			"utf8",
		);
		await writeFile(
			join(installPath, "package", "package.json"),
			JSON.stringify({ name: "cline-internal-bundled-skills-demo" }, null, 2),
			"utf8",
		);
		await writeFile(
			entryPath,
			"export default { name: 'demo', manifest: { capabilities: ['skills'] } };",
			"utf8",
		);
		writeGlobalSettings({
			disabledPlugins: [entryPath, "/tmp/other-plugin.ts"],
		});

		const result = await uninstallPlugin({
			name: "cline-internal-bundled-skills-demo",
		});

		expect(result.installPath).toBe(installPath);
		expect(existsSync(installPath)).toBe(false);
		expect(readGlobalSettings()).toEqual({
			autoUpdateEnabled: true,
			disabledPlugins: ["/tmp/other-plugin.ts"],
			telemetryOptOut: false,
		});
	});

	it("uninstalls a direct plugin file by path", async () => {
		const pluginPath = join(home, ".cline", "plugins", "direct-plugin.ts");
		await mkdir(join(home, ".cline", "plugins"), { recursive: true });
		await writeFile(
			pluginPath,
			"export default { name: 'direct', manifest: { capabilities: ['tools'] } };",
			"utf8",
		);

		const result = await uninstallPlugin({ path: pluginPath });

		expect(result.installPath).toBe(pluginPath);
		expect(existsSync(pluginPath)).toBe(false);
	});

	it.skipIf(process.platform === "win32")(
		"keeps plugin files when MCP settings cleanup fails",
		async () => {
			const pluginPath = join(home, ".cline", "plugins", "mcp-plugin.ts");
			const settingsPath = join(root, "cline_mcp_settings.json");
			process.env.CLINE_MCP_SETTINGS_PATH = settingsPath;
			await mkdir(join(home, ".cline", "plugins"), { recursive: true });
			await writeFile(
				pluginPath,
				"export default { name: 'mcp-plugin', manifest: { capabilities: ['mcp'] } };",
				"utf8",
			);
			await writeFile(
				settingsPath,
				JSON.stringify(
					{
						mcpServers: {
							smoke: {
								transport: {
									type: "stdio",
									command: process.execPath,
									args: ["-e", "process.exit(0)"],
								},
								metadata: {
									source: "plugin",
									pluginName: "mcp-plugin",
									pluginPath,
								},
							},
						},
					},
					null,
					2,
				),
				"utf8",
			);
			chmodSync(settingsPath, 0o444);

			try {
				await expect(uninstallPlugin({ path: pluginPath })).rejects.toThrow();
			} finally {
				chmodSync(settingsPath, 0o644);
			}

			expect(existsSync(pluginPath)).toBe(true);
		},
	);

	// chmod-based deletion failure cannot be simulated on Windows, where read-only
	// directory permissions do not prevent removing files inside them.
	it.skipIf(process.platform === "win32")(
		"keeps disabled plugin settings if file deletion fails",
		async () => {
			const pluginRoot = join(home, ".cline", "plugins");
			const pluginPath = join(pluginRoot, "locked-plugin.ts");
			await mkdir(pluginRoot, { recursive: true });
			await writeFile(
				pluginPath,
				"export default { name: 'locked', manifest: { capabilities: ['tools'] } };",
				"utf8",
			);
			writeGlobalSettings({ disabledPlugins: [pluginPath] });
			chmodSync(pluginRoot, 0o555);

			try {
				await expect(uninstallPlugin({ path: pluginPath })).rejects.toThrow();
				expect(existsSync(pluginPath)).toBe(true);
				expect(readGlobalSettings()).toEqual({
					autoUpdateEnabled: true,
					disabledPlugins: [pluginPath],
					telemetryOptOut: false,
				});
			} finally {
				chmodSync(pluginRoot, 0o755);
			}
		},
	);

	it("reports unmatched names clearly", async () => {
		await expect(uninstallPlugin({ name: "missing-plugin" })).rejects.toThrow(
			/No plugin found matching "missing-plugin"/,
		);
	});
});

import type { ITelemetryService } from "@cline/shared";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import type { ProviderSettings } from "../types/provider-settings";

function createProviderSettingsManager(settings?: ProviderSettings) {
	return {
		getProviderSettings: vi.fn(() => settings),
	};
}

function createStartInput() {
	return {
		config: {
			providerId: "cline",
			modelId: "anthropic/claude-haiku-4.5",
			apiKey: "test-key",
			cwd: "/tmp/project-startup",
			workspaceRoot: "/tmp/project-startup",
			systemPrompt: "system",
			mode: "act" as const,
			enableTools: true,
			enableSpawnAgent: true,
			enableAgentTeams: true,
		},
	};
}

function createSpawnTool() {
	return {
		name: "spawn",
		description: "",
		inputSchema: {},
		execute: vi.fn(),
	};
}

function createTelemetryStub() {
	const captureRequired = vi.fn();
	const capture = vi.fn();
	const telemetry = {
		capture,
		captureRequired,
		setDistinctId: vi.fn(),
		updateCommonProperties: vi.fn(),
		identify: vi.fn(),
	} as unknown as ITelemetryService;
	return { telemetry, capture, captureRequired };
}

function findCapturedEvents(
	capture: ReturnType<typeof vi.fn>,
	event: string,
): { event: string; properties: Record<string, unknown> }[] {
	return capture.mock.calls
		.map(
			([arg]) => arg as { event: string; properties?: Record<string, unknown> },
		)
		.filter((arg) => arg.event === event)
		.map((arg) => ({ event: arg.event, properties: arg.properties ?? {} }));
}

// These tests assert that prepareLocalRuntimeBootstrap drives the workspace
// lifecycle telemetry funnel through the telemetry service it is given,
// covering the wire-up that core-events.test.ts and workspace-telemetry.test.ts
// only verify in isolation.
describe("prepareLocalRuntimeBootstrap startup telemetry", () => {
	beforeEach(async () => {
		// Each test imports prepareLocalRuntimeBootstrap fresh after vi.resetModules
		// so the workspace-telemetry de-duplication set is reset along with it.
	});

	afterEach(() => {
		vi.resetModules();
		vi.doUnmock("./workspace/workspace-manifest");
	});

	it("emits workspace.initialized via the provided telemetry service exactly once per process", async () => {
		// Stub the manifest so the test does not depend on a real git repo.
		vi.doMock("./workspace/workspace-manifest", () => ({
			buildWorkspaceMetadataWithInfo: vi.fn(async (rootPath: string) => ({
				workspaceInfo: {
					rootPath,
					git: undefined,
					remotes: [],
					branch: undefined,
					commit: undefined,
				},
				workspaceMetadata: "",
				durationMs: 12.5,
				vcsType: "none" as const,
				initError: undefined,
			})),
		}));

		const { prepareLocalRuntimeBootstrap } = await import(
			"./local-runtime-bootstrap"
		);

		const { telemetry, capture, captureRequired } = createTelemetryStub();

		await prepareLocalRuntimeBootstrap({
			input: createStartInput(),
			sessionId: "sess-startup-1",
			providerSettingsManager: createProviderSettingsManager() as never,
			defaultTelemetry: telemetry,
			defaultToolPolicies: undefined,
			onPluginEvent: () => {},
			onTeamEvent: () => {},
			createSpawnTool,
			readSessionMetadata: async () => undefined,
			writeSessionMetadata: async () => {},
		});

		// Workspace lifecycle telemetry now goes through normal `capture` so
		// it respects the user's telemetry opt-out setting.
		expect(captureRequired).not.toHaveBeenCalled();

		const initializedCalls = findCapturedEvents(
			capture,
			"workspace.initialized",
		);
		expect(initializedCalls).toHaveLength(1);
		const firstInitialized = initializedCalls[0];
		if (!firstInitialized) {
			throw new Error("missing workspace.initialized capture");
		}
		const props = firstInitialized.properties;
		expect(props).toMatchObject({
			root_count: 1,
			vcs_types: ["none"],
			is_multi_root: false,
			has_git: false,
			has_mercurial: false,
			feature_flag_enabled: true,
		});
		expect(typeof props.init_duration_ms).toBe("number");

		// No diagnostics error in this scenario, so init_error must not fire.
		const initErrorCalls = findCapturedEvents(capture, "workspace.init_error");
		expect(initErrorCalls).toHaveLength(0);
	});

	it("emits workspace.init_error when workspace diagnostics report a failure", async () => {
		vi.doMock("./workspace/workspace-manifest", () => ({
			buildWorkspaceMetadataWithInfo: vi.fn(async (rootPath: string) => ({
				workspaceInfo: {
					rootPath,
					git: undefined,
					remotes: [],
					branch: undefined,
					commit: undefined,
				},
				workspaceMetadata: "",
				durationMs: 7.25,
				vcsType: "git" as const,
				initError: {
					errorType: "WorkspaceSetupError",
					message: "git index unreadable",
				},
			})),
		}));

		const { prepareLocalRuntimeBootstrap } = await import(
			"./local-runtime-bootstrap"
		);
		const { telemetry, capture, captureRequired } = createTelemetryStub();

		const input = createStartInput();
		// Use a different workspace path so the workspace-telemetry dedupe set
		// (re-initialized by vi.resetModules) does not need to be cleared
		// across describe blocks.
		input.config.cwd = "/tmp/project-startup-error";
		input.config.workspaceRoot = "/tmp/project-startup-error";

		await prepareLocalRuntimeBootstrap({
			input,
			sessionId: "sess-startup-error",
			providerSettingsManager: createProviderSettingsManager() as never,
			defaultTelemetry: telemetry,
			defaultToolPolicies: undefined,
			onPluginEvent: () => {},
			onTeamEvent: () => {},
			createSpawnTool,
			readSessionMetadata: async () => undefined,
			writeSessionMetadata: async () => {},
		});

		// Workspace lifecycle telemetry now goes through normal `capture` so
		// it respects the user's telemetry opt-out setting.
		expect(captureRequired).not.toHaveBeenCalled();

		const initializedCalls = findCapturedEvents(
			capture,
			"workspace.initialized",
		);
		expect(initializedCalls).toHaveLength(1);

		const initErrorCalls = findCapturedEvents(capture, "workspace.init_error");
		expect(initErrorCalls).toHaveLength(1);
		const firstInitError = initErrorCalls[0];
		if (!firstInitError) {
			throw new Error("missing workspace.init_error capture");
		}
		const props = firstInitError.properties;
		expect(props).toMatchObject({
			error_type: "WorkspaceSetupError",
			error_message: "git index unreadable",
			fallback_to_single_root: true,
			workspace_count: 1,
		});
	});

	it("does not throw and emits no telemetry when no telemetry service is provided", async () => {
		vi.doMock("./workspace/workspace-manifest", () => ({
			buildWorkspaceMetadataWithInfo: vi.fn(async (rootPath: string) => ({
				workspaceInfo: {
					rootPath,
					git: undefined,
					remotes: [],
					branch: undefined,
					commit: undefined,
				},
				workspaceMetadata: "",
				durationMs: 1,
				vcsType: "none" as const,
				initError: undefined,
			})),
		}));

		const { prepareLocalRuntimeBootstrap } = await import(
			"./local-runtime-bootstrap"
		);

		await expect(
			prepareLocalRuntimeBootstrap({
				input: createStartInput(),
				sessionId: "sess-startup-no-telemetry",
				providerSettingsManager: createProviderSettingsManager() as never,
				defaultTelemetry: undefined,
				defaultToolPolicies: undefined,
				onPluginEvent: () => {},
				onTeamEvent: () => {},
				createSpawnTool,
				readSessionMetadata: async () => undefined,
				writeSessionMetadata: async () => {},
			}),
		).resolves.toBeDefined();
	});
});

import {
	existsSync,
	mkdtempSync,
	readFileSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
	buildMcpInstallTransport,
	installMcpServer,
	parseMcpHeaders,
	parseMcpInstallArgs,
	uninstallMcpServer,
} from "./mcp-install";

function readSettings(settingsPath: string): Record<string, unknown> & {
	mcpServers?: Record<string, { transport?: unknown }>;
} {
	return JSON.parse(readFileSync(settingsPath, "utf8")) as Record<
		string,
		unknown
	> & {
		mcpServers?: Record<string, { transport?: unknown }>;
	};
}

describe("MCP install service", () => {
	let root = "";

	beforeEach(() => {
		root = mkdtempSync(join(tmpdir(), "core-mcp-install-"));
	});

	afterEach(() => {
		rmSync(root, { recursive: true, force: true });
	});

	it("builds stdio installs without shell-joining command args", () => {
		expect(
			buildMcpInstallTransport({
				name: "fs",
				targetArgs: [
					"npx",
					"-y",
					"@modelcontextprotocol/server-filesystem",
					"/tmp/my dir",
				],
			}),
		).toEqual({
			name: "fs",
			transport: {
				type: "stdio",
				command: "npx",
				args: ["-y", "@modelcontextprotocol/server-filesystem", "/tmp/my dir"],
			},
			warnings: [],
		});
	});

	it("installs mcp-remote marketplace entries as native HTTP servers", () => {
		expect(
			buildMcpInstallTransport({
				name: "linear",
				targetArgs: ["npx", "-y", "mcp-remote", "https://mcp.linear.app/mcp"],
			}),
		).toEqual({
			name: "linear",
			transport: {
				type: "streamableHttp",
				url: "https://mcp.linear.app/mcp",
			},
			warnings: [],
		});
	});

	it("installs remote MCP servers with headers into the settings file", () => {
		const settingsPath = join(root, "cline_mcp_settings.json");
		const result = installMcpServer({
			name: "docs",
			transport: "http",
			headers: ["Authorization: Bearer <token>"],
			targetArgs: ["https://example.com/mcp", "--header=X-Extra: yes"],
			settingsPath,
		});

		expect(result).toEqual({
			name: "docs",
			status: "installed",
			transport: {
				type: "streamableHttp",
				url: "https://example.com/mcp",
				headers: {
					Authorization: "Bearer <token>",
					"X-Extra": "yes",
				},
			},
			warnings: [
				'Header "Authorization" looks like it contains a placeholder. Update it in MCP settings before using this server.',
			],
		});
		expect(readSettings(settingsPath).mcpServers?.docs).toEqual({
			transport: result.transport,
		});
	});

	it("parses marketplace-style MCP install args in core", () => {
		expect(
			parseMcpInstallArgs([
				"docs",
				"--transport=http",
				"https://example.com/mcp",
				"--header",
				"Authorization: Bearer <token>",
				"--header=X-Extra: yes",
			]),
		).toEqual({
			name: "docs",
			transport: "http",
			targetArgs: ["https://example.com/mcp"],
			headers: ["Authorization: Bearer <token>", "X-Extra: yes"],
		});

		expect(() => parseMcpInstallArgs([])).toThrow(
			/Marketplace MCP install args/,
		);
	});

	it("treats -- in marketplace args as the end of option parsing", () => {
		// Marketplace catalog entries mark the start of the stdio command with
		// "--" (matching the CLI form `cline mcp install name -- npx ...`).
		// The separator must not become the command itself.
		const parsed = parseMcpInstallArgs([
			"aikido",
			"--",
			"npx",
			"-y",
			"@aikidosec/mcp@1.0.9",
		]);
		expect(parsed.targetArgs).toEqual(["npx", "-y", "@aikidosec/mcp@1.0.9"]);
		expect(buildMcpInstallTransport(parsed).transport).toEqual({
			type: "stdio",
			command: "npx",
			args: ["-y", "@aikidosec/mcp@1.0.9"],
		});
	});

	it("keeps transport-like values as stdio command args for direct builder input", () => {
		expect(
			buildMcpInstallTransport({
				name: "custom",
				targetArgs: ["node", "server.js", "--transport", "ipc"],
			}).transport,
		).toEqual({
			type: "stdio",
			command: "node",
			args: ["server.js", "--transport", "ipc"],
		});
	});

	it("preserves existing MCP settings while adding a server", () => {
		const settingsPath = join(root, "cline_mcp_settings.json");
		writeFileSync(
			settingsPath,
			JSON.stringify(
				{
					mcpServers: {
						existing: {
							transport: { type: "stdio", command: "node" },
							disabled: true,
						},
					},
					customTopLevelKey: true,
				},
				null,
				2,
			),
			"utf8",
		);

		installMcpServer({
			name: "new-server",
			targetArgs: ["node", "server.js"],
			settingsPath,
		});

		const written = readSettings(settingsPath);
		expect(written.customTopLevelKey).toBe(true);
		expect(written.mcpServers).toMatchObject({
			existing: {
				transport: { type: "stdio", command: "node" },
				disabled: true,
			},
			"new-server": {
				transport: {
					type: "stdio",
					command: "node",
					args: ["server.js"],
				},
			},
		});
	});

	it("creates a missing settings file on first install", () => {
		const settingsPath = join(root, "nested", "settings.json");

		installMcpServer({
			name: "fs",
			targetArgs: ["node", "server.js"],
			settingsPath,
		});

		expect(existsSync(settingsPath)).toBe(true);
		expect(readSettings(settingsPath).mcpServers?.fs).toEqual({
			transport: {
				type: "stdio",
				command: "node",
				args: ["server.js"],
			},
		});
	});

	it("rejects invalid install arguments before writing settings", () => {
		const settingsPath = join(root, "settings.json");

		expect(() =>
			installMcpServer({
				name: "fs",
				settingsPath,
			}),
		).toThrow(/requires a command/);
		expect(() =>
			installMcpServer({
				name: "bad",
				transport: "http",
				targetArgs: ["file:///tmp/server"],
				settingsPath,
			}),
		).toThrow(/only http and https are supported/);
		expect(existsSync(settingsPath)).toBe(false);
	});
});

describe("parseMcpHeaders", () => {
	it("keeps commas and colons inside a header value", () => {
		expect(parseMcpHeaders(["Accept: a, b", "X-Time: 12:30"]).headers).toEqual({
			Accept: "a, b",
			"X-Time": "12:30",
		});
	});

	it("rejects headers --header would reject", () => {
		expect(() => parseMcpHeaders(["no-colon"])).toThrow(/Invalid MCP header/);
		expect(() => parseMcpHeaders(["Empty:"])).toThrow(/Invalid MCP header/);
		expect(() => parseMcpHeaders(["Bad Name: x"])).toThrow(
			/Invalid MCP header name/,
		);
	});
});

describe("MCP uninstall service", () => {
	let root = "";

	beforeEach(() => {
		root = mkdtempSync(join(tmpdir(), "core-mcp-uninstall-"));
	});

	afterEach(() => {
		rmSync(root, { recursive: true, force: true });
	});

	function writeSettings(settings: unknown): string {
		const settingsPath = join(root, "cline_mcp_settings.json");
		writeFileSync(settingsPath, JSON.stringify(settings, null, 2), "utf8");
		return settingsPath;
	}

	function seededSettings(): Record<string, unknown> {
		return {
			mcpServers: {
				docs: {
					transport: {
						type: "streamableHttp",
						url: "https://example.com/mcp",
						headers: { Authorization: "Bearer token" },
					},
				},
				keep: {
					transport: { type: "stdio", command: "node", args: ["server.js"] },
					disabled: true,
					autoApprove: ["read_file"],
				},
			},
			customTopLevelKey: { nested: true },
		};
	}

	it("removes only the requested server and preserves everything else", () => {
		const settingsPath = writeSettings(seededSettings());

		expect(uninstallMcpServer({ name: "docs", settingsPath })).toEqual({
			name: "docs",
			status: "uninstalled",
		});

		const written = readSettings(settingsPath);
		expect(Object.keys(written.mcpServers ?? {})).toEqual(["keep"]);
		expect(written.mcpServers?.keep).toEqual({
			transport: { type: "stdio", command: "node", args: ["server.js"] },
			disabled: true,
			autoApprove: ["read_file"],
		});
		expect(written.customTopLevelKey).toEqual({ nested: true });
	});

	it("trims the requested server name", () => {
		const settingsPath = writeSettings(seededSettings());

		expect(uninstallMcpServer({ name: "  docs  ", settingsPath })).toEqual({
			name: "docs",
			status: "uninstalled",
		});
		expect(Object.keys(readSettings(settingsPath).mcpServers ?? {})).toEqual([
			"keep",
		]);
	});

	it("keeps an empty mcpServers map after removing the last server", () => {
		const settingsPath = writeSettings({
