import { describe, expect, it, vi } from "vitest";
import { createOAuthClientCallbacks } from "./client";

describe("auth/client createOAuthClientCallbacks", () => {
	it("emits instructions and URL and forwards prompts", async () => {
		const onOutput = vi.fn();
		const onPrompt = vi.fn().mockResolvedValue("value");
		const callbacks = createOAuthClientCallbacks({ onOutput, onPrompt });

		callbacks.onAuth({
			url: "https://example.com/auth",
			instructions: "Open your browser",
		});
		const answer = await callbacks.onPrompt({ message: "Enter code" });

		expect(answer).toBe("value");
		expect(onPrompt).toHaveBeenCalledWith({ message: "Enter code" });
		expect(onOutput).toHaveBeenNthCalledWith(1, "Open your browser");
		expect(onOutput).toHaveBeenNthCalledWith(2, "https://example.com/auth");
	});

	it("tries opening URL and reports opener errors", async () => {
		const openUrl = vi.fn().mockRejectedValue(new Error("failed"));
		const onOpenUrlError = vi.fn();
		const callbacks = createOAuthClientCallbacks({
			onPrompt: vi.fn().mockResolvedValue(""),
			openUrl,
			onOpenUrlError,
		});

		callbacks.onAuth({ url: "https://example.com/auth" });
		await Promise.resolve();

		expect(openUrl).toHaveBeenCalledWith("https://example.com/auth");
		expect(onOpenUrlError).toHaveBeenCalledTimes(1);
		expect(onOpenUrlError.mock.calls[0]?.[0]).toMatchObject({
			url: "https://example.com/auth",
		});
	});

	it("reports synchronous opener errors without aborting auth output", () => {
		const openUrl = vi.fn(() => {
			throw new Error("missing opener");
		});
		const onOpenUrlError = vi.fn();
		const onOutput = vi.fn();
		const callbacks = createOAuthClientCallbacks({
			onPrompt: vi.fn().mockResolvedValue(""),
			onOutput,
			openUrl,
			onOpenUrlError,
		});

		expect(() =>
			callbacks.onAuth({ url: "https://example.com/auth" }),
		).not.toThrow();
		expect(openUrl).toHaveBeenCalledWith("https://example.com/auth");
		expect(onOpenUrlError).toHaveBeenCalledTimes(1);
		expect(onOpenUrlError.mock.calls[0]?.[0]).toMatchObject({
			url: "https://example.com/auth",
		});
		expect(onOutput).toHaveBeenLastCalledWith("https://example.com/auth");
	});

	it("forwards onServerListening to the returned callbacks", () => {
		const onServerListening = vi.fn();
		const callbacks = createOAuthClientCallbacks({
			onPrompt: vi.fn().mockResolvedValue(""),
			onServerListening,
		});

		expect(callbacks.onServerListening).toBe(onServerListening);
	});

	it("forwards onServerClose to the returned callbacks", () => {
		const onServerClose = vi.fn();
		const callbacks = createOAuthClientCallbacks({
			onPrompt: vi.fn().mockResolvedValue(""),
			onServerClose,
		});

		expect(callbacks.onServerClose).toBe(onServerClose);
	});

	it("leaves onServerListening and onServerClose undefined when not provided", () => {
		const callbacks = createOAuthClientCallbacks({
			onPrompt: vi.fn().mockResolvedValue(""),
		});

		expect(callbacks.onServerListening).toBeUndefined();
		expect(callbacks.onServerClose).toBeUndefined();
	});
});

import { describe, expect, it, vi } from "vitest";
import {
	isCredentialLikelyExpired,
	parseAuthorizationInput,
	parseOAuthError,
	resolveAuthorizationCodeInput,
	resolveUrl,
} from "./utils";

describe("auth/utils", () => {
	it("parses auth input from full URL with provider", () => {
		const parsed = parseAuthorizationInput(
			"http://localhost/callback?code=test-code&state=s1&provider=google",
			{
				includeProvider: true,
			},
		);
		expect(parsed).toEqual({
			code: "test-code",
			state: "s1",
			provider: "google",
		});
	});

	it("parses auth input from hash format when enabled", () => {
		const parsed = parseAuthorizationInput("abc123#state1", {
			allowHashCodeState: true,
		});
		expect(parsed).toEqual({ code: "abc123", state: "state1" });
	});

	it("builds resolved URLs from base + path", () => {
		expect(resolveUrl("https://example.com/", "/token")).toBe(
			"https://example.com/token",
		);
	});

	it("parses OAuth error payloads from string and object forms", () => {
		expect(
			parseOAuthError(
				JSON.stringify({
					error: "invalid_grant",
					error_description: "expired",
				}),
			),
		).toEqual({
			code: "invalid_grant",
			message: "expired",
		});
		expect(
			parseOAuthError(
				JSON.stringify({ error: { type: "unauthorized", message: "denied" } }),
			),
		).toEqual({
			code: "unauthorized",
			message: "denied",
		});
	});

	it("resolves code from callback result", async () => {
		const result = await resolveAuthorizationCodeInput({
			waitForCallback: async () => ({
				url: new URL("http://localhost"),
				code: "from-callback",
				state: "s1",
			}),
			cancelWait: () => {},
		});
		expect(result).toEqual({
			code: "from-callback",
			state: "s1",
			provider: undefined,
			error: undefined,
		});
	});

	it("resolves code from manual input when callback does not provide one", async () => {
		const cancelWait = vi.fn();
		const result = await resolveAuthorizationCodeInput({
			waitForCallback: async () => null,
			cancelWait,
			onManualCodeInput: async () => "code=manual&state=manual-state",
		});
		expect(cancelWait).toHaveBeenCalled();
		expect(result).toEqual({
			code: "manual",
			state: "manual-state",
			provider: undefined,
		});
	});

	it("throws when manual input rejects", async () => {
		await expect(
			resolveAuthorizationCodeInput({
				waitForCallback: async () => null,
				cancelWait: () => {},
				onManualCodeInput: async () => {
					throw new Error("cancelled");
				},
			}),
		).rejects.toThrow("cancelled");
	});

	it("checks token expiry with configurable buffer", () => {
		const nowSpy = vi.spyOn(Date, "now").mockReturnValue(1_000);
		expect(isCredentialLikelyExpired({ expires: 1_500 }, 600)).toBe(true);
		expect(isCredentialLikelyExpired({ expires: 3_000 }, 600)).toBe(false);
		nowSpy.mockRestore();
	});
});
